import awkward as ak


class ToyReweight:
    """Custom MC weight with symmetric variations for PocketCoffea analysis."""

    name = "toy_reweight"
    has_variations = True

    @staticmethod
    def weight(events):
        """Nominal weight: LHEWeight_originalXWGTUP normalized to 1."""
        return events.LHEWeight_originalXWGTUP / ak.mean(events.LHEWeight_originalXWGTUP)

    @staticmethod
    def weight_up(events):
        """Weight with +5% variation."""
        nominal = events.LHEWeight_originalXWGTUP / ak.mean(events.LHEWeight_originalXWGTUP)
        return nominal * 1.05

    @staticmethod
    def weight_down(events):
        """Weight with -5% variation."""
        nominal = events.LHEWeight_originalXWGTUP / ak.mean(events.LHEWeight_originalXWGTUP)
        return nominal * 0.95


# Usage in PocketCoffea configuration:
# cfg = {
#     "weights_classes": [ToyReweight],
#     ...
